Given a string s, containing lowercase alphabetical characters. The task is to print all non-empty substrings of the given string.Examples : Input :  s = "abc"Output :  "a", "ab", "abc", "b", "bc", "c"Input :  s = "ab"Output :  "a",  "ab",  "b"Input :  s = "a"Output :  "a"Table of Content[Approach 1] Using Iteration - O(n^3) Time and O(n^3) Space [Approach 2] Using Recursion - O(n^3) Time and O(n^3) Space[Approach 1] Using Iteration - O(n^3) Time and O(n^3) Space The idea is to use two nested loops. The outer loop selects the starting index from 0 to n-1, and for each starting index, the inner loop selects the ending index from that position up to n-1.
            C++

    #include <iostream>
using namespace std;

// Function to find all substrings
vector<string> findSubstrings(string &s) {

    // to store all substrings
    vector<string> res;

    for(int i = 0; i < s.length(); i++) {
        for(int j = i; j < s.length(); j++) {

            // substr function takes starting index
            // and length as parameters
            res.push_back(s.substr(i, j-i+1));
        }
    }

    return res;
}

int main() {
    string s = "abc";
    vector<string> res = findSubstrings(s);
    for(auto i:res) {
        cout<< i <<" ";
    }
    return 0;
}


